// Vite 风格的 `?raw` 后缀导入(vitest 用例读组件源码做静态断言用)。
// Next/Turbopack 不认这个后缀,只有测试侧的 vite 管线会解析,故 tsc 需要一条环境声明,
// 否则 apps/web 全量 typecheck 恒红(TS2307),连带把整条守门链拖进 --no-verify。
declare module '*.tsx?raw' {
  const source: string
  export default source
}

declare module '*.ts?raw' {
  const source: string
  export default source
}
